-- This program creates the bookings table for BK-02. It stores the
-- listing, the customer, the lifecycle status, and the UTC start and
-- end so a booking can move from pending through confirmed and
-- completed, or to cancelled.
--
-- File:   V3__create_bookings_table.sql
-- Course: AUCSC 325
--

CREATE TABLE bookings (
    -- To identify each booking; generated by the database
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- To point at the listing the customer booked
    listing_id  BIGINT NOT NULL,
    -- To point at the customer who made the booking
    customer_id BIGINT NOT NULL,
    -- To store PENDING, CONFIRMED, COMPLETED, or CANCELLED
    status      VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    -- To store the slot start in UTC
    start_time  TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    -- To store the slot end in UTC
    end_time    TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    -- To keep status inside the BK-02 lifecycle
    CONSTRAINT ck_bookings_status CHECK (
        status IN ('PENDING', 'CONFIRMED', 'COMPLETED', 'CANCELLED')
    ),
    -- To reject a slot that ends at or before it starts
    CONSTRAINT ck_bookings_end_after_start CHECK (end_time > start_time),
    -- To keep a booking only when its listing still exists
    CONSTRAINT fk_bookings_listing
        FOREIGN KEY (listing_id) REFERENCES listings (id),
    -- To keep a booking only when its customer account still exists
    CONSTRAINT fk_bookings_customer
        FOREIGN KEY (customer_id) REFERENCES users (id)
);

-- To look up the bookings on a listing
CREATE INDEX idx_bookings_listing_id ON bookings (listing_id);

-- To look up the bookings a customer made
CREATE INDEX idx_bookings_customer_id ON bookings (customer_id);
